import React, { useEffect, useState } from "react";
import ProductList from "./components/ProductList";
import Cart from "./components/Cart";
import Login from "./components/Login";
import Register from "./components/Register";
import { fetchProducts } from "./api";

export default function App() {
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [view, setView] = useState("products"); // products | cart | login | register

  useEffect(() => {
    fetchProducts().then(res => setProducts(res || []));
  }, []);

  // ---------- ADD TO CART ----------
  function handleAdd(product) {
    setCart(prev => {
      const exists = prev.find(p => p.id === product.id);

      if (exists) {
        return prev.map(p =>
          p.id === product.id
            ? { ...p, qty: p.qty + 1 }
            : p
        );
      }

      return [
        ...prev,
        {
          id: product.id,
          name: product.name,
          price: product.price,
          qty: 1
        }
      ];
    });
  }

  function handleOrderPlaced() {
    setCart([]);
    setView("products");
  }

  return (
    <div className="container">
      <h1>E-Commerce</h1>

      {/* NAVBAR */}
      <div className="top-buttons">
        <button onClick={() => setView("products")}>Products</button>
        <button onClick={() => setView("cart")}>Cart ({cart.length})</button>
        <button onClick={() => setView("login")}>Login</button>
        <button onClick={() => setView("register")}>Register</button>
      </div>

      {view === "products" && (
        <ProductList products={products} onAdd={handleAdd} />
      )}

      {view === "cart" && (
        <Cart cart={cart} setCart={setCart} onOrderPlaced={handleOrderPlaced} />
      )}

      {view === "login" && <Login onSuccess={() => setView("products")} />}
      {view === "register" && <Register onSuccess={() => setView("login")} />}
    </div>
  );
}
